    clean = fm.replace("v115@", "").replace("?", "").replace("/", "_").replace(
        "*", "_"
    );
    return (clean + ".txt");
}

"""
    Compute the nth triangle number
    """
def nth_triangle(n: Any) -> object {
    return ((n * (n + 1)) // 2);
}
